SELECT b.*, p.project_name, sc.contract_name
FROM budgets b
LEFT JOIN projects p ON b.project_id = p.id
LEFT JOIN subcontractor_contracts sc ON b.contract_id = sc.id
WHERE 1=1

    AND b.project_id = #{projectId}


    AND b.contract_id = #{contractId}


    AND b.status = #{status}

LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM budgets b
WHERE 1=1

    AND b.project_id = #{projectId}


    AND b.contract_id = #{contractId}


    AND b.status = #{status}
